**NinjaScript — real-time daily stats**
```csharp
public class DailyStats : Indicator
{
    private double dayOpen, dayHigh, dayLow;

    protected override void OnStateChange()
    {
        if (State == State.SetDefaults)
        {
            Name      = "DailyStats";
            IsOverlay = true;
            AddPlot(Brushes.Blue,  "DayHigh");
            AddPlot(Brushes.Red,   "DayLow");
            AddPlot(Brushes.White, "DayOpen");
        }
        Calculate = Calculate.OnBarClose;
    }

    protected override void OnBarUpdate()
    {
        if (Bars.IsFirstBarOfSession)
        {
            dayOpen = Open[0];
            dayHigh = High[0];
            dayLow  = Low[0];
        }
        else
        {
            dayHigh = Math.Max(dayHigh, High[0]);
            dayLow  = Math.Min(dayLow,  Low[0]);
        }
        Values[0][0] = dayHigh;
        Values[1][0] = dayLow;
        Values[2][0] = dayOpen;
    }
}
```

**Pine Script v6**
```pine
