var float dayLow  = na
var float dayOpen = na
if timeframe.change('D') or na(dayOpen)
    dayOpen := open
    dayHigh := high
    dayLow  := low
else
    dayHigh := math.max(dayHigh, high)
    dayLow  := math.min(dayLow, low)
plot(dayHigh, 'Day High', color=color.blue,  linewidth=2)
plot(dayLow,  'Day Low',  color=color.red,   linewidth=2)
plot(dayOpen, 'Day Open', color=color.white, linewidth=1)
```

**ATR(14) for NQ 03-19**

Using Wilder's smoothing: `ATR[0] = (ATR[1] × (14−1) + TR[0]) / 14`

